import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"アクションメニューと即時プレビュー","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. アクションメニューの詳細","slug":"_1-アクションメニューの詳細","link":"#_1-アクションメニューの詳細","children":[{"level":3,"title":"標準アクション一覧","slug":"標準アクション一覧","link":"#標準アクション一覧","children":[]},{"level":3,"title":"アクションメニューの操作と絞り込み","slug":"アクションメニューの操作と絞り込み","link":"#アクションメニューの操作と絞り込み","children":[]}]},{"level":2,"title":"2. メインウィンドウの一覧機能","slug":"_2-メインウィンドウの一覧機能","link":"#_2-メインウィンドウの一覧機能","children":[]},{"level":2,"title":"3. QuickLook 即時プレビュー機能","slug":"_3-quicklook-即時プレビュー機能","link":"#_3-quicklook-即時プレビュー機能","children":[{"level":3,"title":"プレビューにキーボード操作はない","slug":"プレビューにキーボード操作はない","link":"#プレビューにキーボード操作はない","children":[]},{"level":3,"title":"多彩なファイル形式に対応","slug":"多彩なファイル形式に対応","link":"#多彩なファイル形式に対応","children":[]},{"level":3,"title":"レイアウトとダイアログの自動回避","slug":"レイアウトとダイアログの自動回避","link":"#レイアウトとダイアログの自動回避","children":[]}]},{"level":2,"title":"4. プラグインのリッチテキスト・対話型プレビュー","slug":"_4-プラグインのリッチテキスト・対話型プレビュー","link":"#_4-プラグインのリッチテキスト・対話型プレビュー","children":[]},{"level":2,"title":"5. サードパーティ製 QuickLook との連携（任意）","slug":"_5-サードパーティ製-quicklook-との連携-任意","link":"#_5-サードパーティ製-quicklook-との連携-任意","children":[]},{"level":2,"title":"6. ファイル占有の解除","slug":"_6-ファイル占有の解除","link":"#_6-ファイル占有の解除","children":[]},{"level":2,"title":"7. お気に入りに追加","slug":"_7-お気に入りに追加","link":"#_7-お気に入りに追加","children":[]},{"level":2,"title":"8. 名前を変更","slug":"_8-名前を変更","link":"#_8-名前を変更","children":[]}],"relativePath":"ja-JP/user-guide/actions-and-preview.md","filePath":"ja-JP/user-guide/actions-and-preview.md","lastUpdated":1791112464000}`),a={name:`ja-JP/user-guide/actions-and-preview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="アクションメニューと即時プレビュー" tabindex="-1">アクションメニューと即時プレビュー <a class="header-anchor" href="#アクションメニューと即時プレビュー" aria-label="Permalink to “アクションメニューと即時プレビュー”">​</a></h1><p>Lertaro はファイル検索に加え、コンテキストアクション機能とプレビューパネルを統合しており、エクスプローラーを開くことなくファイルの確認、管理、共有を行えます。</p><h2 id="_1-アクションメニューの詳細" tabindex="-1">1. アクションメニューの詳細 <a class="header-anchor" href="#_1-アクションメニューの詳細" aria-label="Permalink to “1. アクションメニューの詳細”">​</a></h2><p>クイックウィンドウでは、選択中の結果に対して <code>Ctrl+O</code> または方向キー <code>→</code> を押すとコンテキストアクションメニューが展開されます。ただし <code>→</code> はキャレットがすでに検索語の末尾にあるときだけ機能するため、文章の途中を編集中にカーソル移動が奪われることはありません。同じキーはファイルダイアログ<strong>外</strong>のインラインウィンドウでも使えますが、「開く/保存/フォルダーの参照」ダイアログにドッキングしたウィンドウにはアクションメニュー自体がありません。メイン検索ウィンドウではどちらのキーにも割り当てられておらず、結果を右クリックするか <code>Apps</code> キー（<code>Shift+F10</code>）を押すと同じメニューが開きます。</p><p>すべての行にメニューがあるわけではありません。<strong>さらに表示</strong> 行、プラグインが提供した結果、URL のお気に入り、どのプロバイダーも引き受けなかったインスタント結果、クイックウィンドウ以外でのアプリ、そしてすべてのファイルダイアログではメニューを表示しません。そうした行では、空のパネルを開く代わりにメニューキーは何もしません。</p><h3 id="標準アクション一覧" tabindex="-1">標準アクション一覧 <a class="header-anchor" href="#標準アクション一覧" aria-label="Permalink to “標準アクション一覧”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">アクション名</th><th style="text-align:left;">既定のキー</th><th style="text-align:left;">機能説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>開く</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">システムの既定プログラムでファイルを開くか、アプリを起動します。メイン検索ウィンドウでは、<code>Enter</code> は<strong>選択したすべての行</strong>に適用され、ダブルクリックはダブルクリックした 1 行のみに作用します。</td></tr><tr><td style="text-align:left;"><strong>エクスプローラーで表示</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">親フォルダーを開き、エクスプローラー上で対象ファイルを選択した状態で表示します。</td></tr><tr><td style="text-align:left;"><strong>管理者として実行</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">管理者権限でプログラムを実行します（実行可能ファイル、ショートカット、バッチ等に対応）。</td></tr><tr><td style="text-align:left;"><strong>フルパスをコピー</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">絶対パス（例: <code>D:\\Projects\\app.exe</code>）をクリップボードにコピーします。</td></tr><tr><td style="text-align:left;"><strong>名前をコピー</strong></td><td style="text-align:left;"><code>Shift+C</code></td><td style="text-align:left;">選択したファイルやフォルダーの名前を、パスなしでクリップボードにコピーします。</td></tr><tr><td style="text-align:left;"><strong>ファイルのコピー</strong></td><td style="text-align:left;"><code>Ctrl+C</code></td><td style="text-align:left;">ファイル自体をクリップボードに格納し、エクスプローラーや別フォルダーに直接貼り付け可能にします。</td></tr><tr><td style="text-align:left;"><strong>切り取り / ファイルのコピー</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">ファイル自体をクリップボードに格納し、エクスプローラーや別フォルダーに直接貼り付け可能にします。検索ボックス内でテキストが選択されている間は、これらはテキストに対する操作のままです。</td></tr><tr><td style="text-align:left;"><strong>ここへ貼り付け</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">フォルダーが選択されているとき、クリップボード上のファイルをそのディレクトリへ直接貼り付け、ファイルが選択されているときはその親フォルダーへ貼り付けます。実行には実体のファイル一覧がクリップボードに必要なので、検索語へテキストを貼り付ける操作は影響を受けません。</td></tr><tr><td style="text-align:left;"><strong>削除（ごみ箱へ移動）</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">選択したファイルやフォルダーをごみ箱へ安全に移動します。修飾キーのないこのキーがアクションに届くのは、キャレットがすでに検索語の末尾にあるときだけであり、その後にごみ箱への移動を問うネイティブの確認ダイアログが表示されます。</td></tr><tr><td style="text-align:left;"><strong>完全に削除</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">選択項目を完全に削除します（ネイティブの「完全に削除しますか」の確認ダイアログが表示され、そのあとでは復元できません）。</td></tr><tr><td style="text-align:left;"><strong>名前を変更</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Windows Shell を使って、存在するファイルまたはフォルダー 1 件の名前を変更します。ダイアログでは名前部分があらかじめ選択されます。</td></tr><tr><td style="text-align:left;"><strong>Windows 右クリックメニュー</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">Windows エクスプローラーの標準コンテキストメニュー（送る、サードパーティ製ツールの項目を含む）を展開します。</td></tr></tbody></table><h3 id="アクションメニューの操作と絞り込み" tabindex="-1">アクションメニューの操作と絞り込み <a class="header-anchor" href="#アクションメニューの操作と絞り込み" aria-label="Permalink to “アクションメニューの操作と絞り込み”">​</a></h3><ul><li><strong>入力して即時絞り込み</strong>：アクションメニューが開いた状態で文字を入力すると、アクション名で素早く絞り込めます（例: <code>copy</code> と入力してコピー関連の操作を即座に抽出）。絞り込みボックスがキーボードを受け持つため、ほかへ移動しても元の検索語には一切触れません。</li><li><strong>アクセスキー文字</strong>：アクションには強調表示された 1 文字が付くことがあります。そのキーを押すと<strong>即座にアクションが実行されます</strong>（ハイライトされるだけではありません）。ただしそれは絞り込みボックスがまだ空のあいだだけで、絞り込みのために打った 1 文字目が奪われることはありません。</li><li><strong>独立した検索ボックス</strong>：アクションメニューには独立した検索ボックスがあり、開くと自動的にフォーカスされます。アクションの絞り込みはメインの検索語を変更しません。階層を切り替えると絞り込み文字列が消去され、新しい階層の検索ボックスにフォーカスが移ります。</li><li><strong>フローティングアクションパネル</strong>：クイックウィンドウ、クイック起動パネル、メイン検索ウィンドウでは、アクションが対象項目の近くにフローティングパネルとして表示されます。クイック起動パネルは一時的にアクション一覧の最大作業高さへ広がり、閉じると元のコンパクトな高さに戻ります。</li><li><strong>階層ナビゲーション</strong>：サブメニューを持つ項目（「送る」など）で <code>→</code>、<code>Tab</code> または <code>Enter</code> を押して下の階層に進み、<code>←</code> またはテキストが空の状態で <code>Backspace</code> を押すと親階層に戻ります。入れ子のメニューでは <code>Escape</code> または右クリックで親階層に戻り、ルートではアクションメニューを閉じます。</li><li><strong>ナビゲーションキーが引き続き動作する</strong>：設定済みの次/前の項目のホットキー（既定は <code>Ctrl+N</code> / <code>Ctrl+P</code>）は、アクション一覧の中でもハイライトを移動します。先頭と末尾をまたいでループ移動し、区切り線・見出し・無効化されたアクションはスキップします。<code>Tab</code> は、それらのキーのいずれかに割り当てていない場合に限りサブメニューへ入ります。</li><li><strong>外側をクリックして閉じる</strong>：フローティングパネルの外側をクリックするとパネルが閉じます。ホストが対応している場合、パネルを開いたまま別の結果を右クリックすると対象だけがその場で置き換わります。</li><li><strong>アクションのショートカット</strong>：パネルにフォーカスがある間は、プロバイダーが定義したアクションショートカットを使用できます。実行後はフローティングパネルだけが閉じ、メイン検索ウィンドウまたはクイック起動パネルは開いたままになります。</li></ul><h2 id="_2-メインウィンドウの一覧機能" tabindex="-1">2. メインウィンドウの一覧機能 <a class="header-anchor" href="#_2-メインウィンドウの一覧機能" aria-label="Permalink to “2. メインウィンドウの一覧機能”">​</a></h2><p>メイン検索ウィンドウ（<code>Ctrl+F</code>）は、大量のファイル管理と詳細なブラウジングのために設計されています。</p><ul><li><strong>パス列のダブルクリック移動</strong>：結果一覧の <strong>名前</strong> 列をダブルクリックするとファイルが開き、<strong>パス</strong> 列をダブルクリックするとそのファイルが存在する親フォルダーが直接開きます。ダブルクリックは<em>左</em>ボタンに限られ、列ヘッダーをダブルクリックしても何も起こらず、最大化と復帰はウィンドウ上部の入力欄でない帯をダブルクリックして行います。</li><li><strong>複数選択</strong>：グリッドは通常の Windows リストとして振る舞います。<code>Ctrl</code>+クリックで行を追加または解除し、<code>Shift</code>+クリックで範囲を選択し、そのあとの <code>Enter</code> は<strong>選択したすべての行</strong>へ一括で作用しますが、ダブルクリックはダブルクリックした 1 行のみを開きます。すでに選択の一部である行を右クリックすると、その 1 行だけに縮めず選択全体を保ちます。</li><li><strong>ストリーミング結果表示</strong>：数百万件のファイルをスキャンする際も、インデックスエンジンから届いた結果がリアルタイムに順次一覧へ追加されます。検索全体の完了を待つことなく即座に操作が可能で、行が追加されても選択とスクロール位置は保たれます。まったく新しい結果セットのときだけ先頭からやり直します。</li><li><strong>ループナビゲーション</strong>：先頭行で <code>↑</code> を押すと末尾行へ、末尾行で <code>↓</code> を押すと先頭行へループ移動します。同じループはクイックウィンドウとインラインウィンドウでも適用され、まだ何も選択していない状態で <code>↑</code> を押すと末尾行へ、<code>↓</code> を押すと先頭行へ移動します。グループを 1 続きのリストとして<strong>ループせずに</strong>辿るのはクイックパネルだけです。</li><li><strong>横スクロール</strong>：グリッドの上で <code>Shift</code> + ホイールを回すと 1 目盛りにつき 3 列分スクロールします。狭いウィンドウで端の列まで届くための方法です。</li><li><strong>ファイルのドラッグアウト</strong>：任意の行を実際のファイルドロップとしてエクスプローラー、ダイアログ、チャットウィンドウへ直接ドラッグできます。複数選択中のいずれかをドラッグすると<strong>選択全体</strong>が一緒に運ばれます。Lertaro の外へドロップするとウィンドウは隠れますが、ドラッグ中はクローズが待たされるため、ドラッグカーソルが残り込むことはありません。</li><li><strong>選択数の表示</strong>：複数の行を選択すると、ステータスバーに結果総数とともに現在の選択数が表示されます。</li><li><strong>ホバープレビュー</strong>：プレビューパネルが開いた状態で行にポインターを動かすと、選択を変えずにプレビュー対象だけ切り替わります。候補を次々となぞってから、戻ってきた行で <code>Enter</code> を押すことができます。</li><li><strong>ウィンドウのドラッグ移動とサイズ記憶</strong>：ウィンドウ上部の余白部分はドラッグバーとして機能し、手動で調整したウィンドウサイズは次回起動時にも自動的に保持されます。</li></ul><h2 id="_3-quicklook-即時プレビュー機能" tabindex="-1">3. QuickLook 即時プレビュー機能 <a class="header-anchor" href="#_3-quicklook-即時プレビュー機能" aria-label="Permalink to “3. QuickLook 即時プレビュー機能”">​</a></h2><p>プレビュー可能な結果で <code>Alt+P</code> を押すと、検索ウィンドウの横にドッキングされたプレビューパネルが表示されます。<strong>行を中クリック</strong>しても同じパネルを開閉できます。ファイルダイアログのインラインウィンドウではどちらも用意されておらず、クイックパネルでは両方使えます。</p><h3 id="プレビューにキーボード操作はない" tabindex="-1">プレビューにキーボード操作はない <a class="header-anchor" href="#プレビューにキーボード操作はない" aria-label="Permalink to “プレビューにキーボード操作はない”">​</a></h3><p>このパネルは意図的にアクティブ化されません。検索ウィンドウからフォーカスを奪うことはないため、入力する先は存在せず、<code>Escape</code> でも閉じません。<code>Alt+P</code> で切り替えるか、ドッキング元のウィンドウを閉じて隠してください。メディア再生バー、スクロールバー、プラグインカードなど、パネルの操作要素はすべてマウス専用で、キーボードのフォーカスはあった場所にそのまま残ります。</p><h3 id="多彩なファイル形式に対応" tabindex="-1">多彩なファイル形式に対応 <a class="header-anchor" href="#多彩なファイル形式に対応" aria-label="Permalink to “多彩なファイル形式に対応”">​</a></h3><ul><li><strong>画像</strong>：JPG、PNG、GIF、BMP、ICO 画像のスケール表示。</li><li><strong>テキストとコード</strong>：TXT、Markdown、JSON、XML、YAML、C#、Python、JS、HTML などを等幅フォントでそのまま表示（シンタックスハイライトなし）。</li><li><strong>音声・動画の即時再生</strong>：動画ファイル（MP4、M4V、WMV、AVI、MOV、MPG/MPEG）と音声ファイル（MP3、WAV、WMA、M4A、AAC）はプレビューを開くと<strong>自動的に再生が開始</strong>され、テーマ連動のミニ再生バー（再生/一時停止、シークバー、再生時間、ミュート）が表示されます。項目の切り替えで即座に停止します。</li><li><strong>フォルダー構造の確認</strong>：フォルダーを選択すると、直下のアイテム上位 30 件がアイコン・サイズ付きで表示されます（隠しファイルやシステムファイルは除外）。</li></ul><h3 id="レイアウトとダイアログの自動回避" tabindex="-1">レイアウトとダイアログの自動回避 <a class="header-anchor" href="#レイアウトとダイアログの自動回避" aria-label="Permalink to “レイアウトとダイアログの自動回避”">​</a></h3><ul><li><strong>画面範囲の自動調整</strong>：プレビューサイズは <a href="./settings/general.html#_4-プレビューウィンドウ-preview-window"><strong>設定 → 一般 → プレビュー</strong></a> で変更可能で、画面外にはみ出さないよう自動制御されます。</li><li><strong>ドッキングする側</strong>：パネルは検索ウィンドウの<strong>右</strong>側にドッキングし、右に収まらないときだけ左へ反転します。広い側を追いかけて移動することはしないため、広いウィンドウをスクロールしても同じ位置に留まります。以降はオーナーのウィンドウを移動・サイズ変更するとついていきます。</li><li><strong>サイズ記憶はセッション単位</strong>：リサイズグリップのドラッグやパネルの移動は、プレビューを使い続けているあいだは記憶されますが、検索ウィンドウが次に隠れるか閉じられた時点で、設定済みのサイズとドッキング側に戻ります。</li><li><strong>ネイティブダイアログの自動回避</strong>：パスワード保護された Office 文書などをプレビューする際、パスワード入力ダイアログが表示されると Lertaro は一時的にウィンドウを隠し、操作完了後に自動復帰します。</li><li><strong>プレビューからのドラッグ＆ドロップ</strong>：プレビューパネルの上部をドラッグすることで、プレビュー中のファイルを外部アプリやエクスプローラーへ直接ドロップできます。フッターバーをドラッグするとパネル自体が移動します。</li></ul><h2 id="_4-プラグインのリッチテキスト・対話型プレビュー" tabindex="-1">4. プラグインのリッチテキスト・対話型プレビュー <a class="header-anchor" href="#_4-プラグインのリッチテキスト・対話型プレビュー" aria-label="Permalink to “4. プラグインのリッチテキスト・対話型プレビュー”">​</a></h2><p>QuickLook はローカルファイルだけでなく、プラグインによる対話型プレビューにも対応しています。</p><ul><li><strong>テーマ適応型リッチテキスト</strong>：WebView2 およびネイティブコンポーネントで描画され、ダーク/ライトテーマに自動追従し、高コントラストフォントと半透明スクロールバーで表示されます。</li><li><strong>多彩なプラグインカード</strong>：辞書検索カード、リアルタイム天気予報、Web スナップショット、API レスポンス確認などの対話型パネルをサポートします。</li></ul><h2 id="_5-サードパーティ製-quicklook-との連携-任意" tabindex="-1">5. サードパーティ製 QuickLook との連携（任意） <a class="header-anchor" href="#_5-サードパーティ製-quicklook-との連携-任意" aria-label="Permalink to “5. サードパーティ製 QuickLook との連携（任意）”">​</a></h2><p>独立したオープンソースツール <strong>QuickLook</strong>（<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub の QL-Win/QuickLook</a>）をお使いの場合、<a href="./settings/plugins.html"><strong>設定 → プラグイン</strong></a> で <strong>QuickLook ブリッジ</strong> プラグインを有効化できます。</p><ul><li><strong>プレビューの委譲</strong>：ローカルの名前付きパイプ経由で外部の QuickLook プロセスに接続し、プレビューウィンドウを Lertaro の横に吸着表示します。</li><li><strong>自動フォールバック</strong>：外部の QuickLook が起動していない場合は、Lertaro 内蔵のプレビューエンジンへ切り替わります。</li></ul><h2 id="_6-ファイル占有の解除" tabindex="-1">6. ファイル占有の解除 <a class="header-anchor" href="#_6-ファイル占有の解除" aria-label="Permalink to “6. ファイル占有の解除”">​</a></h2><p>公式の<strong>ファイル占有解除</strong>プラグインは、存在するファイルを 1 件だけ選択したときにアクションを追加します。ファイルを使用中のプロセス、その PID、実行ファイルのパスを一覧表示し、プロセスにファイルの解放を要求できます。フォルダー、存在しないファイル、複数選択ではアクションを実行できず、占有プロセスがない場合は解放要求ボタンも無効になります。ダイアログはホストのテーマに従い、検索ウィンドウより手前に表示され、Alt+Tab には表示されません。再読み込みにも対応しています。</p><h2 id="_7-お気に入りに追加" tabindex="-1">7. お気に入りに追加 <a class="header-anchor" href="#_7-お気に入りに追加" aria-label="Permalink to “7. お気に入りに追加”">​</a></h2><p>CoreExtensions には、存在するファイルまたはフォルダーを 1 件だけ追加できる<strong>お気に入りに追加</strong>アクションがあります。テーマ対応ダイアログで表示名を入力でき、同じパスがすでにお気に入りの場合はアクションを表示しません。</p><h2 id="_8-名前を変更" tabindex="-1">8. 名前を変更 <a class="header-anchor" href="#_8-名前を変更" aria-label="Permalink to “8. 名前を変更”">​</a></h2><p>CoreExtensions には、存在するファイルまたはフォルダーを 1 件だけ変更できる<strong>名前を変更</strong>アクションがあります。テーマ対応ダイアログには現在の完全な名前が表示され、名前部分があらかじめ選択されます。たとえば <code>report.pdf</code> では <code>report</code> のみが選択され、フォルダーや拡張子のない名前では名前全体が選択されます。<code>Enter</code> で確定し、<code>Esc</code> でキャンセルできます。確定後の名前変更は Windows Shell に委譲されます。</p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};